#include <openvdb/openvdb.h>
#include <openvdb/tools/LevelSetTracker.h>
#include <openvdb/tools/LevelSetFilter.h>
#include <openvdb/tools/LevelSetSphere.h>
#include <openvdb/tools/ChangeBackground.h>
#include <tbb/global_control.h>
#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>
#include <limits>
using namespace openvdb;
void number(double v){if(std::isnan(v))std::cout<<"\"NaN\"";else if(std::isinf(v))std::cout<<(v>0?"\"Infinity\"":"\"-Infinity\"");else std::cout<<v;}
template<class Grid> typename Grid::Ptr shape(int id){using T=typename Grid::ValueType;auto g=tools::createLevelSetSphere<Grid>(4.5f,Vec3f(-0.25f,0.5f,0.25f),0.75f,3.0f);if(id==0)for(auto it=g->tree().beginValueOn();it;++it)it.setValue(*it*T(1.125)+T((it.getCoord().x()+2*it.getCoord().y()-it.getCoord().z())%5)*T(0.03125));if(id==1){g=Grid::create(T(2.25));g->setTransform(math::Transform::createLinearTransform(0.75));g->setGridClass(GRID_LEVEL_SET);for(int x=-5;x<=5;++x)for(int y=-5;y<=5;++y)for(int z=-5;z<=5;++z){T v=T(std::max(std::max(std::abs(x),std::abs(y)),std::abs(z))-3)*T(0.75);if(std::abs(v)<T(2.25))g->tree().setValueOn(Coord(x,y,z),v);else g->tree().setValueOff(Coord(x,y,z),v);}}if(id==2){g=Grid::create(T(3));g->setGridClass(GRID_LEVEL_SET);for(int n=0;n<7;++n)g->tree().setValueOn(Coord(n,0,0),T(n-3));g->tree().addTile(1,Coord(16,0,0),T(-0.5),true);g->tree().addTile(2,Coord(128,0,0),T(0.5),true);g->tree().addTile(3,Coord(4096,0,0),T(-0.5),true);g->tree().addTile(3,Coord(8192,0,0),T(-2),false);g->tree().setValueOff(Coord(0,1,0),std::numeric_limits<T>::quiet_NaN());}return g;}
FloatGrid::Ptr alphaMask(int mode){auto m=FloatGrid::create(0.5f);if(mode==3)m->setTransform(math::Transform::createLinearTransform(1.5));else m->setTransform(math::Transform::createLinearTransform(0.75));for(int x=-12;x<=12;++x)for(int y=-10;y<=10;++y)for(int z=-10;z<=10;++z)m->tree().setValueOn(Coord(x,y,z),float(x+8)*0.0625f);return m;}
BoolTree normMask(){BoolTree m(false);for(int x=-10;x<=10;++x)for(int y=-10;y<=10;++y)for(int z=-10;z<=10;++z)if((x+y+z)%3==0)m.setValueOn(Coord(x,y,z),false);m.addTile(1,Coord(24,0,0),false,true);return m;}
std::vector<Coord> probes(){std::vector<Coord> p;for(int x=-10;x<=10;++x)for(int y=-6;y<=6;y+=2)for(int z=-6;z<=6;z+=2)p.emplace_back(x,y,z);for(Coord c:{Coord(0,1,0),Coord(3,0,0),Coord(6,0,0),Coord(16,0,0),Coord(128,0,0),Coord(4096,0,0),Coord(8192,0,0),Coord(24,0,0)})p.push_back(c);return p;}
template<class Grid>void dump(const Grid& g,const std::vector<Coord>&p){auto&t=g.tree();std::cout<<"{\"background\":";number(double(t.background()));std::cout<<",\"active\":"<<t.activeVoxelCount()<<",\"leaves\":"<<t.leafCount()<<",\"roots\":"<<t.root().getTableSize()<<",\"tiles\":"<<t.activeTileCount()<<",\"samples\":[";bool first=true;for(auto c:p){if(!first)std::cout<<',';first=false;std::cout<<'[';number(double(t.getValue(c)));std::cout<<','<<(t.isValueOn(c)?1:0)<<','<<t.getValueDepth(c)<<']';}std::cout<<"]}";}
const math::BiasedGradientScheme spatial[]={math::FIRST_BIAS,math::SECOND_BIAS,math::THIRD_BIAS,math::WENO5_BIAS,math::HJWENO5_BIAS};
const math::TemporalIntegrationScheme temporal[]={math::TVD_RK1,math::TVD_RK2,math::TVD_RK3};
bool firstCase=true;
template<class Grid>void emit(const char*op,int shapeId,int scheme,int rk,int maskMode,int parameter,const std::vector<Coord>&p){using T=typename Grid::ValueType;if(!firstCase)std::cout<<',';firstCase=false;auto g=shape<Grid>(shapeId);tools::LevelSetFilter<Grid> f(*g);f.setGrainSize(0);f.setSpatialScheme(spatial[scheme]);f.setTemporalScheme(temporal[rk]);f.setNormCount(parameter);auto mask=alphaMask(maskMode);if constexpr(std::is_same_v<T,float>){if(maskMode==4){mask=FloatGrid::create(g->treePtr());mask->setTransform(math::Transform::createLinearTransform(1.5));}}const FloatGrid* maskp=maskMode==0?nullptr:mask.get();f.setMaskRange(0.125f,0.875f);f.invertMask(maskMode==2);std::string operation(op);if(operation=="normalize"){if(maskMode){auto m=normMask();f.normalize(&m);}else f.normalize();}else if(operation=="track")f.track();else if(operation=="prune"){f.setTrimming(static_cast<tools::lstrack::TrimMode>(maskMode));f.prune();}else if(operation=="dilate")f.dilate(maskMode);else if(operation=="erode")f.erode(maskMode);else if(operation=="resize")f.resize(maskMode);else if(operation=="mean")f.mean(1,maskp);else if(operation=="gaussian")f.gaussian(1,maskp);else if(operation=="median")f.median(1,maskp);else if(operation=="laplacian")f.laplacian(maskp);else if(operation=="curvature")f.meanCurvature(maskp);else if(operation=="fillet")f.fillet(maskp);else if(operation=="offset")f.offset(T(-0.65),maskp);else if(operation=="background")tools::changeLevelSetBackground(g->tree(),T(4));else if(operation=="asymmetric")tools::changeAsymmetricLevelSetBackground(g->tree(),T(4),T(-5));else if(operation=="generalBackground")tools::changeBackground(g->tree(),T(4));std::cout<<"{\"type\":\""<<(sizeof(T)==4?"float":"double")<<"\",\"operation\":\""<<op<<"\",\"shape\":"<<shapeId<<",\"scheme\":"<<scheme<<",\"rk\":"<<rk<<",\"mask\":"<<maskMode<<",\"count\":"<<parameter<<",\"result\":";dump(*g,p);std::cout<<'}';}
template<class Grid>void cases(const std::vector<Coord>&p){for(int s=0;s<5;++s)for(int t=0;t<3;++t)for(int m=0;m<2;++m)emit<Grid>("normalize",0,s,t,m,2,p);for(int s:{0,4})for(int m=0;m<2;++m){emit<Grid>("track",m,s,0,0,3,p);emit<Grid>("dilate",m,s,1,1,2,p);}for(int m=0;m<4;++m)emit<Grid>("prune",2,0,0,m,0,p);emit<Grid>("erode",0,0,0,1,0,p);emit<Grid>("resize",0,0,0,2,0,p);emit<Grid>("resize",0,0,0,4,1,p);emit<Grid>("dilate",0,0,0,2,0,p);for(const char*op:{"mean","gaussian","median","laplacian","curvature","fillet","offset"})for(int m=0;m<4;++m)emit<Grid>(op,op==std::string("fillet")?1:0,4,0,m,2,p);for(const char*op:{"background","asymmetric","generalBackground"})emit<Grid>(op,2,0,0,0,0,p);}
int main(){tbb::global_control threadLimit(tbb::global_control::max_allowed_parallelism,1);std::cout<<std::setprecision(17);auto p=probes();std::cout<<"{\"upstreamCommit\":\"f42248c35a9f7bb30641a8a74d9075ce7d1ddcaf\",\"coordinates\":[";for(size_t i=0;i<p.size();++i){if(i)std::cout<<',';std::cout<<'['<<p[i].x()<<','<<p[i].y()<<','<<p[i].z()<<']';}std::cout<<"],\"cases\":[";cases<FloatGrid>(p);cases<DoubleGrid>(p);emit<FloatGrid>("offset",0,4,0,4,2,p);std::cout<<"]}";}
